#!/usr/bin/env python3"""Тестовый скрипт для проверки новых агентов"""import requestsimport jsonimport timedef test_agents_api():    """Тестировать API агентов"""    base_url = "http://localhost:8000"        # Ждем запуска сервера    print("⏳ Ожидание запуска сервера...")    for i in range(10):        try:            response = requests.get(f"{base_url}/docs", timeout=2)            if response.status_code == 200:                print("✅ Сервер запущен!")                break        except:            time.sleep(1)            print(f"Попытка {i+1}/10...")    else:        print("❌ Не удалось подключиться к серверу")        return        # Тестируем получение агентов    try:        print("\n🔍 Тестируем получение всех агентов...")        response = requests.get(f"{base_url}/agents/")                if response.status_code == 200:            agents = response.json()            print(f"✅ Получено {len(agents)} агентов:")                        for agent in agents:                print(f"  - {agent['name']} (ID: {agent['id']}, категория: {agent.get('category', 'не указана')})")                        # Проверяем наличие новых агентов            calculator_found = any(agent['name'] == 'Калькулятор' for agent in agents)            deepseek_found = any(agent['name'] == 'DeepSeek Assistant' for agent in agents)                        print(f"\n📊 Результаты проверки:")            print(f"  - Калькулятор: {'✅ найден' if calculator_found else '❌ не найден'}")            print(f"  - DeepSeek Assistant: {'✅ найден' if deepseek_found else '❌ не найден'}")                    else:            print(f"❌ Ошибка получения агентов: {response.status_code}")                except Exception as e:        print(f"❌ Ошибка при тестировании: {e}")if __name__ == "__main__":    test_agents_api()